style.css:
body {
    background: #f4eadf !important;
}

input {
    background: #fff8ef !important;
    border: 2px solid #8b6248 !important;
    border-radius: 25px !important;
    color: #4a2c1d !important;
}

input::placeholder {
    color: #8b6b57 !important;
}

a {
    color: #70452f !important;
}

button {
    background: #ead7c4 !important;
    color: #4a2c1d !important;
    border-radius: 20px !important;
}

button:hover {
    background: #d5b496 !important;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    color: #4a2c1d !important;
}
